                return max(self.longestSubstring(sub, k) for sub in s.split(ch))
        return len(s)

class Solution {
public:
    int longestSubstring(string s, int k) {
        int n = s.length();
        if (n < k) return 0;
        vector<int> counts(26, 0);
        for (char c : s) counts[c - 'a']++;
        for (int i = 0; i < n; i++) {
            if (counts[s[i] - 'a'] < k) {
                int left = longestSubstring(s.substr(0, i), k);
                int right = longestSubstring(s.substr(i + 1), k);
                return max(left, right);
            }
        }
        return n;
    }
};

class Solution {
    public int longestSubstring(String s, int k) {
        int n = s.length();
        if (n < k) return 0;
        int[] counts = new int[26];
        for (int i = 0; i < n; i++) counts[s.charAt(i) - 'a']++;
        for (int i = 0; i < n; i++) {
            if (counts[s.charAt(i) - 'a'] < k) {
                int left = longestSubstring(s.substring(0, i), k);
                int right = longestSubstring(s.substring(i + 1), k);
                return Math.max(left, right);
            }
        }
        return n;
    }
}

var longestSubstring = function(s, k) {
    const n = s.length;
    if (n < k) return 0;
    const counts = new Array(26).fill(0);
    for (let i = 0; i < n; i++) counts[s.charCodeAt(i) - 97]++;
    for (let i = 0; i < n; i++) {
        if (counts[s.charCodeAt(i) - 97] < k) {
            const left = longestSubstring(s.substring(0, i), k);
            const right = longestSubstring(s.substring(i + 1), k);
            return Math.max(left, right);
        }
    }
    return n;
};
